/// <summary>
/// MPJ_19962_MDRPOTransactionalMissingFields kavya 25/3/2022
/// Class extension
/// </summary>
class METPurchFormLetter_PurchOrderEventHandler
{
}

Method.Source:
    /// <summary>
    /// Event handler method to validate while confirming
    /// </summary>
    /// <param name="args">args</param>
    [PostHandlerFor(classStr(PurchFormLetter_PurchOrder), methodStr(PurchFormLetter_PurchOrder, validate))]
    public static void PurchFormLetter_PurchOrder_Post_validate(XppPrePostArgs args)
    {
        Valid ret = args.getReturnValue();
        boolean conversionFound;

        if(args.getThis() is PurchFormLetter_Confirmation || args.getThis() is PurchFormLetter_ConfirmationRequest)
        {
            PurchFormLetter_PurchOrder PurchFormLetter_PurchOrder = args.getThis() as PurchFormLetter_PurchOrder;

            PurchTable      PurchTable = PurchFormLetter_PurchOrder.purchTable();
            purchLine       purchLine;           
            METPurchTable   metPurchTable;
            select firstonly RecId from purchLine
                exists join metPurchTable
                where purchLine.PurchId == PurchTable.PurchId       &&
                      purchLine.PurchId == metPurchTable.PurchId    &&
                ! purchLine.IsDeleted                               &&
                purchLine.Blocked       == NoYes::No                &&
                !purchLine.METPOLinePromotionIHG                    &&
                metPurchTable.POPromotionIHG;
                    
            if(!purchLine.RecId)
            {
                ret = checkFailed("@MET:METPOPromotionValidation");
            }
            
            
            MetItemSiteSettingsSetup        itemSiteSettingSetup;
            InventDim                       inventDim;
            Qty                             warehouseQty;
            METPurchLine                    metPurchLine;

            while select metPurchLine
                join PurchUnit, ItemId, PurchQty from purchLine
                    where purchLine.PurchId == PurchTable.PurchId
                       && purchLine.RecId == metPurchLine.PurchLine
                           join UnitId from itemSiteSettingSetup
                            where itemSiteSettingSetup.ItemId == purchLine.ItemId
                                exists join InventDim
                                    where inventDim.inventDimId == purchLine.InventDimId
                                       && inventDim.InventSiteId == itemSiteSettingSetup.InventSiteId
            {
                
                [conversionFound, warehouseQty] = METPurchFormLetter_PurchOrderEventHandler::getWarehouseUnitAndQty(purchLine, itemSiteSettingSetup.UnitId);
                if(!conversionFound)
                {
                    break;
                }
                else
                {
                    ttsbegin;
                    metPurchLine.selectForUpdate(true);
                    metPurchLine.WarehouseUnitId = itemSiteSettingSetup.UnitId;
                    metPurchLine.WarehouseQty = warehouseQty;
                    metPurchLine.doUpdate();
                    ttscommit;
                }
            }
            if(!conversionFound)
            {
                ret = ret && checkFailed(strFmt("@MET:POWarehouseUnitValidation", purchLine.ItemId));
            }

        }
        args.setReturnValue(ret);
    }

    /// <summary>
    /// Method to determine if conversion exists  between the purchase and warehouse units
    /// </summary>
    /// <param name = "purchLine">the purchase line</param>
    /// <param name = "warehouseUnit">the warehouse UOM</param>
    /// <returns>True if UOM conversion is found/else false and the warehouse quantity</returns>
    public static container getWarehouseUnitAndQty(PurchLine purchLine, UnitOfMeasureSymbol warehouseUnit)
    {
        UnitOfMeasureConversion     unitOfMeasureConversion;
        boolean                     isUnitConversionPresent = true;
        UnitOfMeasureSymbol         purchUnit = purchLine.PurchUnit;
        ItemId                      itemId = purchLine.ItemId;
        Qty                         warehouseQty;
        InventTableModule           inventTableModule;
        UnitOfMeasureSymbol         inventoryUnit;

        select firstonly UnitId from inventTableModule
                where inventTableModule.ItemId      == itemId
                    && inventTableModule.ModuleType == ModuleInventPurchSales::Invent;

        if(inventTableModule.UnitId)
        {
            inventoryUnit = inventTableModule.UnitId;
        }

        if(purchUnit == warehouseUnit)
        {
            isUnitConversionPresent = true;
            warehouseQty = purchLine.PurchQty;
        }
        else if(warehouseUnit != METConstants::emptyString)
        {
            unitOfMeasureConversion = UnitOfMeasureConversion::findByConversion(
                            UnitOfMeasure::findBySymbol(warehouseUnit).RecId,
                            UnitOfMeasure::findBySymbol(purchUnit).RecId,
                            EcoResProduct::findByProductNumber(purchLine.ItemId).RecId);

            if(unitOfMeasureConversion.RecId)
            {
                isUnitConversionPresent = true;
                if(purchUnit == inventoryUnit)
                {
                    warehouseQty = purchLine.PurchQty / unitOfMeasureConversion.Factor;
                }
                else
                {
                    warehouseQty = purchLine.PurchQty * unitOfMeasureConversion.Factor;
                }
            }
            else
            {
                //Check purchase to warehouse conversion
                unitOfMeasureConversion = UnitOfMeasureConversion::findByConversion(
                            UnitOfMeasure::findBySymbol(purchUnit).RecId,
                            UnitOfMeasure::findBySymbol(warehouseUnit).RecId,
                            EcoResProduct::findByProductNumber(purchLine.ItemId).RecId);

                if(unitOfMeasureConversion.RecId)
                {
                    isUnitConversionPresent = true;
                    if(purchUnit == inventoryUnit)
                    {
                        warehouseQty = purchLine.PurchQty / unitOfMeasureConversion.Factor;
                    }
                    else
                    {
                        warehouseQty = purchLine.PurchQty * unitOfMeasureConversion.Factor;
                    }
                }
                else
                {
                    isUnitConversionPresent = false;
                }
            }
        }

        return [isUnitConversionPresent, warehouseQty];
    }
